-- =====================================================
-- STAGE 6: SALES ANALYSIS
-- Project  : Olist E-Commerce Analytics
-- Database : Olist_Ecommerce_Analytics
-- =====================================================


-- =====================================================
-- Exercise 1: Calculate Total Revenue
-- Business Question:
-- What is the total product revenue generated by Olist?
-- =====================================================

SELECT
    SUM(price) AS total_revenue
FROM dbo.order_items;


-- =====================================================
-- Exercise 2: Monthly Revenue
-- Business Question:
-- How much revenue did Olist generate each month?
-- =====================================================

SELECT
    YEAR(order_purchase_timestamp) AS yearly,
    MONTH(order_purchase_timestamp) AS montly,
    SUM(oi.price) AS montly_revenue
FROM dbo.order_items AS oi
LEFT JOIN dbo.orders AS o
    ON oi.order_id = o.order_id
GROUP BY
    YEAR(order_purchase_timestamp),
    MONTH(order_purchase_timestamp)
ORDER BY
    yearly,
    montly;


-- =====================================================
-- Exercise 3: Yearly Revenue
-- Business Question:
-- How much total revenue did Olist generate each year?
-- =====================================================

SELECT
    YEAR(order_purchase_timestamp) AS yearly,
    SUM(oi.price) AS montly_revenue
FROM dbo.order_items AS oi
LEFT JOIN dbo.orders AS o
    ON oi.order_id = o.order_id
GROUP BY 
    YEAR(order_purchase_timestamp)
ORDER BY 
    yearly;


-- =====================================================
-- Exercise 4: Revenue by Product Category
-- Business Question:
-- Which product category generates the most revenue for Olist?
-- Make sure to have category name in English.
-- =====================================================

SELECT
    pcn.product_category_name_english AS category,
    SUM(oi.price) AS revenue
FROM dbo.order_items AS oi
LEFT JOIN dbo.products AS p
    ON oi.product_id = p.product_id
LEFT JOIN dbo.product_category_name_translation AS pcn
    ON p.product_category_name = pcn.product_category_name
GROUP BY 
    pcn.product_category_name_english
ORDER BY 
    revenue DESC;



-- =====================================================
-- Exercise 5: Top 10 Products by Revenue
-- Business Question:
-- Which individual products generate the highest revenue?
-- =====================================================

SELECT TOP 10
    product_id AS product_id,
    SUM(price) AS revenue
FROM dbo.order_items
GROUP BY 
    product_id
ORDER BY 
    revenue DESC;


-- =====================================================
-- Exercise 6: Average Order Value (AOV)
-- Business Question:
-- What is the average revenue generated per order on Olist?
-- =====================================================

SELECT
    ROUND(
        SUM(price) * 1.0 /
            (SELECT
                COUNT(DISTINCT(order_id)) AS total_orders
            FROM dbo.orders ),2 ) AS avg_revenue
FROM dbo.order_items;


-- =====================================================
-- Exercise 7: State-wise Revenue
-- Business Question:
-- Which Brazilian states generate the highest product revenue for Olist?
-- =====================================================

SELECT
    c.customer_state AS state,
    SUM(oi.price) AS revenue
FROM dbo.order_items AS oi
INNER JOIN dbo.orders AS o
    ON oi.order_id = o.order_id
INNER JOIN dbo.customers AS c
    ON o.customer_id = c.customer_id
GROUP BY 
    c.customer_state
ORDER BY 
    revenue DESC;


-- =====================================================
-- Exercise 8: Payment Method Analysis
-- Business Question:
-- Which payment methods are most commonly used by Olist customers?
-- =====================================================

SELECT
    payment_type,
    COUNT(DISTINCT(order_id)) AS total_payments,
    SUM(payment_value) AS payment_values
FROM dbo.order_payments
GROUP BY payment_type
ORDER BY payment_values DESC;


-- =====================================================
-- END OF STAGE 6: SALES ANALYSIS
-- =====================================================